import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { isEnabled } from "@/lib/feature-flags";
import * as orgRepo from "@/server/repositories/organization-repository";
import { buildFlagContext, toggleFlag } from "@/server/services/feature-flag-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("tmp override check", () => {
  it("switches an override off and on again, leaving others untouched", async () => {
    const tenant = await createTenant("tmp-flag-free", "free");
    const { owner } = tenant.actors;
    const orgId = tenant.org.id;

    let org = await toggleFlag(owner, { orgId, flag: "kanban_board", enabled: true });
    org = await toggleFlag(owner, { orgId, flag: "csv_export", enabled: true });
    expect(org.settings.enabledFlagOverrides.sort()).toEqual(["csv_export", "kanban_board"]);
    expect(isEnabled("kanban_board", buildFlagContext(owner, org))).toBe(true);

    org = await toggleFlag(owner, { orgId, flag: "kanban_board", enabled: false });
    expect(org.settings.enabledFlagOverrides).toEqual(["csv_export"]);
    const stored = await orgRepo.findOrgById(orgId);
    expect(stored?.settings.enabledFlagOverrides).toEqual(["csv_export"]);
    expect(isEnabled("kanban_board", buildFlagContext(owner, stored!))).toBe(false);
    expect(isEnabled("csv_export", buildFlagContext(owner, stored!))).toBe(true);

    org = await toggleFlag(owner, { orgId, flag: "kanban_board", enabled: true });
    expect(org.settings.enabledFlagOverrides.sort()).toEqual(["csv_export", "kanban_board"]);
  });

  it("rejects a non-overridable flag and stores nothing", async () => {
    const tenant = await createTenant("tmp-flag-webhooks", "free");
    const { owner } = tenant.actors;
    await expect(
      toggleFlag(owner, { orgId: tenant.org.id, flag: "webhooks", enabled: true }),
    ).rejects.toThrow(/cannot be overridden/);
    const stored = await orgRepo.findOrgById(tenant.org.id);
    expect(stored?.settings.enabledFlagOverrides).toEqual([]);
  });

  it("ignores a stored override on a non-overridable flag", async () => {
    const tenant = await createTenant("tmp-flag-stored", "free");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { enabledFlagOverrides: ["webhooks"] },
    });
    const stored = await orgRepo.findOrgById(tenant.org.id);
    expect(isEnabled("webhooks", buildFlagContext(tenant.actors.owner, stored!))).toBe(false);
  });

  it("keeps stored overrides when a settings patch omits them", async () => {
    const tenant = await createTenant("tmp-flag-patch", "free");
    const { owner } = tenant.actors;
    await toggleFlag(owner, { orgId: tenant.org.id, flag: "kanban_board", enabled: true });
    const updated = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 9 },
    });
    expect(updated.settings.enabledFlagOverrides).toEqual(["kanban_board"]);
    expect(updated.settings.digestHourUtc).toBe(9);
  });
});

